/**
 * Verification for the spreadsheet (.xlsx) reader.
 *
 * Run: node dsh-doc-attach/tests/test-xlsx-format.mjs
 *
 * The workbook is GENERATED by `make-xlsx-fixture.py` — an .xlsx is a zip of XML
 * parts, so the suite runs anywhere Python does and needs no spreadsheet
 * application. The fixture is shaped to exercise the paths this reader actually
 * takes: a shared-string table, an inline string, a number, a boolean, a gap in
 * a row, a blank row, and two worksheets.
 *
 * The unit of a block here is a ROW, and the checks insist the block carries the
 * coordinates a reader can look up (worksheet + real row number) rather than
 * only this tool's own block counter.
 */
import assert from 'node:assert/strict'
import { writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { DocumentExtractionError, PythonDocumentBackend } from '../lib/extract/document-python.mjs'
import { buildTools } from '../plugins/read-document.mjs'
import { PYTHON, cleanUp, ensureXlsxFixture, scratchDir, suite } from './fixture.mjs'

const CACHE = scratchDir('cache-xlsx')
const SCRATCH = scratchDir('scratch-xlsx')
const BOOK = ensureXlsxFixture(SCRATCH)

const { check, finish } = suite('Spreadsheet (.xlsx) verification')
console.log(`interpreter: ${PYTHON}`)
console.log(`workbook   : ${BOOK}`)
console.log('')

/** Fresh backend per check keeps memoized probe state from leaking. */
function backend(options = {}) {
  return new PythonDocumentBackend({ pythonPath: PYTHON, cacheDir: CACHE, ...options })
}

/** The tool set, wired to this machine's interpreter. */
function tools() {
  return buildTools({ pythonPath: PYTHON, cacheDir: CACHE, defaultWindow: 12, maxWindow: 120 })
}

// ── shape ─────────────────────────────────────────────────────────────────
await check('stats reports the row unit and counts non-empty rows', async () => {
  const stats = await backend().stats(BOOK)
  assert.equal(stats.format, 'xlsx')
  assert.equal(stats.unit, 'row')
  // 4 rows in the first worksheet (one blank row dropped) + 2 in the second.
  assert.equal(stats.blockCount, 6, `expected 6 blocks, got ${stats.blockCount}`)
  assert.equal(stats.textLayer, true)
})

await check('a spreadsheet has no heading outline', async () => {
  const stats = await backend().stats(BOOK)
  assert.deepEqual(stats.outline, [], 'rows must not be invented as headings')
})

await check('every block names its worksheet and its real row number', async () => {
  const { blocks } = await backend().extract(BOOK, { start: 1, count: 20 })
  for (const block of blocks) {
    assert.equal(block.kind, 'row', `block ${block.index} kind`)
    assert.equal(typeof block.sheet, 'string', `block ${block.index} lost its sheet`)
    assert.equal(typeof block.row, 'number', `block ${block.index} lost its row number`)
  }
})

// ── dropped content must not renumber anything ────────────────────────────
await check('a blank row is dropped while row numbers stay real', async () => {
  const { blocks } = await backend().extract(BOOK, { start: 1, count: 20 })
  assert.ok(!blocks.some(block => block.row === 4), 'the blank row 4 must not become a block')
  // Block 4 is worksheet row 5: skipping a blank row must not renumber what follows.
  assert.equal(blocks[3].index, 4)
  assert.equal(blocks[3].row, 5)
})

// ── the three value paths ────────────────────────────────────────────────
await check('shared strings decode as UTF-8 text', async () => {
  const { blocks } = await backend().extract(BOOK, { start: 2, count: 1 })
  assert.equal(blocks[0].text, '香港 | 120 | 已确认')
})

await check('a gapped row keeps its column alignment', async () => {
  const { blocks } = await backend().extract(BOOK, { start: 1, count: 1 })
  // Column B is absent in row 1; the blank must sit in the middle, not be
  // collapsed away, or "报名人数" would appear to be the city column.
  assert.equal(blocks[0].text, '城市 |  | 报名人数 | 备注')
})

await check('an inline string and a boolean render as text', async () => {
  const { blocks } = await backend().extract(BOOK, { start: 4, count: 1 })
  assert.equal(blocks[0].text, '合计 | 180 | TRUE')
})

// ── worksheets ────────────────────────────────────────────────────────────
await check('sheets keep workbook order and are attributed separately', async () => {
  const { blocks } = await backend().extract(BOOK, { start: 1, count: 20 })
  const names = [...new Set(blocks.map(block => block.sheet))]
  assert.deepEqual(names, ['报名记录', 'Notes'])
})

await check('the second worksheet resolves through the relationship table', async () => {
  const { blocks } = await backend().extract(BOOK, { start: 5, count: 2 })
  assert.equal(blocks[0].sheet, 'Notes')
  assert.equal(blocks[0].text, 'Type | Text')
  assert.equal(blocks[1].sheet, 'Notes')
  assert.equal(blocks[1].text, 'memo | follow up in May')
})

// ── search carries the coordinate, not just the block index ───────────────
await check('search reports the worksheet and row of a hit', async () => {
  const result = await backend().search(BOOK, { query: '九龙' })
  assert.equal(result.hitCount, 1)
  const hit = result.hits[0]
  assert.equal(hit.sheet, '报名记录')
  assert.equal(hit.row, 3)
  assert.ok(hit.snippet.includes('九龙'), `snippet: ${hit.snippet}`)
  assert.equal(hit.occurrences, 1)
})

// ── the citation a caller sees ────────────────────────────────────────────
await check('document_read cites the worksheet and row', async () => {
  const out = await tools().read.execute({ path: BOOK, start: 4, count: 1 })
  assert.ok(out.includes('报名记录 第 5 行'), `read output must name the coordinate:\n${out}`)
  assert.ok(out.includes('合计 | 180 | TRUE'), out)
  assert.ok(out.includes('共 6 行'), `unit word must be 行:\n${out}`)
})

await check('document_search cites the worksheet and row', async () => {
  const out = await tools().search.execute({ path: BOOK, query: '九龙' })
  assert.ok(out.includes('报名记录 第 3 行'), `search output must name the coordinate:\n${out}`)
  assert.ok(out.includes('命中'), out)
})

await check('document_outline describes the workbook without headings', async () => {
  const out = await tools().outline.execute({ path: BOOK })
  assert.ok(out.includes('共 6 行'), out)
  assert.ok(!out.includes('标题大纲'), `a workbook has no heading outline:\n${out}`)
})

// ── failure modes ─────────────────────────────────────────────────────────
await check('a .xlsx that is not a zip rejects as UNREADABLE', async () => {
  const fake = join(SCRATCH, 'not-really.xlsx')
  writeFileSync(fake, 'plain text wearing an xlsx extension')
  await assert.rejects(
    () => backend().extract(fake, { start: 1, count: 1 }),
    (error) => error instanceof DocumentExtractionError && error.code === 'UNREADABLE',
  )
})

await check('a missing workbook rejects as NOT_FOUND', async () => {
  await assert.rejects(
    () => backend().stats(join(SCRATCH, 'nope.xlsx')),
    (error) => error instanceof DocumentExtractionError && error.code === 'NOT_FOUND',
  )
})

cleanUp(CACHE)
cleanUp(SCRATCH)
finish()
